import argparse
import csv
import json
import os
import random

def main(args):
    # args is a list of command-line argument strings
    parser = argparse.ArgumentParser()
    parser.add_argument('--input_path', required=True)
    parser.add_argument('--output_dir', required=True)
    parser.add_argument('--seed', type=int, default=42)
    parsed = parser.parse_args(args)

    seed = parsed.seed
    output_dir = parsed.output_dir
    input_path = parsed.input_path

    # Read input file - using tab delimiter as per "tabular format" description
    # But let's be flexible - check if file uses comma or tab
    # Actually let's just use tab since that's most likely for "tabular format" with comma-separated labels
    with open(input_path, 'r', newline='', encoding='utf-8') as f:
        reader = csv.reader(f, delimiter='\t')  # Tab-separated
        raw_rows = []
        for row in reader:
            if not row or (len(row) == 0):
                continue
