    output_dir = parsed.output_dir
    input_path = parsed.input_path

    # Read input file - using tab delimiter as "tabular format" with comma-separated labels suggests tabs between columns
    with open(input_path, 'r', newline='', encoding='utf-8') as f:
        reader = csv.reader(f, delimiter='\t')
        raw_rows = []
        for row in reader:
            if not row or (len(row) == 0):
                continue
            sample_id = row[0].strip()
            labels_str = row[1].strip() if len(row) > 1 else ""
            labels = [label.strip() for label in labels_str.split(',')]
            raw_rows.append((sample_id, labels))

    # Compute label combination frequencies from raw data (before shuffling)
    def normalize_labels(labels):
        sorted_labels = sorted(labels)  # alphabetical sort
        return ','.join(sorted_labels)

    combo_counts = {}
    for sample_id, labels in raw_rows:
        combo_key = normalize_labels(labels)
        combo_counts[combo_key] = combo_counts.get(combo_key, 0) + 1

    unique_combos = list(combo_counts.keys())
    unique_combos_sorted = sorted(unique_combos, key=lambda k: combo_counts[k])  # rarest first

    # Shuffle the samples before splitting
    random.seed(seed)
    shuffled_rows = [(s[0], s[1]) for s in raw_rows]
    random.shuffle(shuffled_rows)

    train_samples = []
    val_samples = []
    test_samples = []

    for combo_key in unique_combos_sorted:
        combo_samples = []
        for sample_id, labels in shuffled_rows:
            if normalize_labels(labels) == combo_key:
                combo_samples.append((sample_id, labels))

        n = len(combo_samples)
        n_train = int(n * 0.70)
        n_val = int(n * 0.15)
        n_test = n - n_train - n_val

        train_samples.extend(combo_samples[:n_train])
        val_samples.extend(combo_samples[n_train:n_train + n_val])
        test_samples.extend(combo_samples[n_train + n_val:])

    # Write output files matching input format (tab-separated)
    os.makedirs(output_dir, exist_ok=True)

    with open(os.path.join(output_dir, 'train.csv'), 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f, delimiter='\t')
        for sample_id, labels in train_samples:
            labels_str = ','.join(labels)
            writer.writerow([sample_id, labels_str])

    with open(os.path.join(output_dir, 'val.csv'), 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f, delimiter='\t')
        for sample_id, labels in val_samples:
            labels_str = ','.join(labels)
            writer.writerow([sample_id, labels_str])

    with open(os.path.join(output_dir, 'test.csv'), 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f, delimiter='\t')
        for sample_id, labels in test_samples:
            labels_str = ','.join(labels)
            writer.writerow([sample_id, labels_str])

    # Count label frequencies for report
    train_label_freq = {}
    val_label_freq = {}
    test_label_freq = {}

    for sample_id, labels in train_samples:
        for label in labels:
            train_label_freq[label] = train_label_freq.get(label, 0) + 1

    for sample_id, labels in val_samples:
        for label in labels:
            val_label_freq[label] = val_label_freq.get(label, 0) + 1

    for sample_id, labels in test_samples:
        for label in labels:
            test_label_freq[label] = test_label_freq.get(label, 0) + 1

    # Count combinations for report
    train_combo_freq = {}
    val_combo_freq = {}
    test_combo_freq = {}

    for sample_id, labels in train_samples:
        combo_key = normalize_labels(labels)
        train_combo_freq[combo_key] = train_combo_freq.get(combo_key, 0) + 1

    for sample_id, labels in val_samples:
        combo_key = normalize_labels(labels)
        val_combo_freq[combo_key] = val_combo_freq.get(combo_key, 0) + 1

    for sample_id, labels in test_samples:
        combo_key = normalize_labels(labels)
        test_combo_freq[combo_key] = test_combo_freq.get(combo_key, 0) + 1

    report = {
        "samples": {
            "train": len(train_samples),
            "val": len(val_samples),
            "test": len(test_samples)
        },
        "label_distribution": {
            "train": train_label_freq,
            "val": val_label_freq,
            "test": test_label_freq
        },
        "label_combinations": {
            "train": train_combo_freq,
            "val": val_combo_freq,
            "test": test_combo_freq
        }
    }

    with open(os.path.join(output_dir, 'report.json'), 'w', encoding='utf-8') as f:
        json.dump(report, f, sort_keys=True)

    return 0

